def parse(txt):
    lines=txt.split('\n')
    ins=[];outs=[]
    i=0
    while i<len(lines):
        if lines[i].startswith('Demo pair') and 'input' in lines[i]:
            i+=1; grid=[]
            while i<len(lines) and lines[i] and lines[i][0].isdigit():
                grid.append([int(x) for x in lines[i].split()]); i+=1
            ins.append(grid)
        if lines[i:i+1] and lines[i].startswith('Demo pair') and 'output' in lines[i]:
            i+=1; grid=[]
            while i<len(lines) and lines[i] and lines[i][0].isdigit():
                grid.append([int(x) for x in lines[i].split()]); i+=1
            outs.append(grid)
        i+=1
    return ins,outs

